use serde_json::{Value, Map};
use std::collections::{HashMap, HashSet};

pub fn solve(input: Value) -> Value {
    let input_map = input.as_object().unwrap();
    let n = input_map["n"].as_u64().unwrap() as usize;
    let edges = input_map["edges"].as_array().unwrap();

    let mut graph: HashMap<usize, Vec<usize>> = HashMap::new();
    let mut in_degree: HashMap<usize, i64> = HashMap::new();

    for edge in edges {
        let edge_array = edge.as_array().unwrap();
        let from = edge_array[0].as_u64().unwrap() as usize;
        let to = edge_array[1].as_u64().unwrap() as usize;

        graph.entry(from).or_insert_with(Vec::new).push(to);
        *in_degree.entry(from).or_insert(0) += 1;
        *in_degree.entry(to).or_insert(0) += 0;
    }

    let mut zero_indegree: HashSet<usize> = in_degree.iter().filter(|&(_, &deg)| deg == 0).map(|(&v, _)| v).collect();
    let mut topological_order: Vec<usize> = Vec::new();

    while !zero_indegree.is_empty() {
        if zero_indegree.len() > 1 {
            return Value::Null;
        }

        let node = *zero_indegree.iter().next().unwrap();
        zero_indegree.remove(&node);
        topological_order.push(node);

        if let Some(neighbors) = graph.get(&node) {
            for &neighbor in neighbors {
                *in_degree.entry(neighbor).or_insert(0) -= 1;
                if *in_degree.get(&neighbor).unwrap() == 0 {
                    zero_indegree.insert(neighbor);
                }
            }
        }
    }

    if topological_order.len() != n {
        return Value::Null;
    }

    Value::Array(topological_order.into_iter().map(|v| Value::Number(v.into())).collect())
}
